def skill():
    x, be = symbols('x be')
    f = 5 + x**2*(x - be)**2
    cand = solve(f.subs(x, 1) - 9, be)
    good = [b0 for b0 in cand if diff(f, x).subs(be, b0).subs(x, 2) < 0]
    assert len(good) == 1
    return f.subs(be, good[0]).subs(x, 4)

def standard():
    x, p, q, a, b, c = symbols('x p q a b c')
    f = x**4 + a*x**3 + b*x**2 + c*x + 5
    eq = Poly(expand(f - 5 - (x**2 + p*x + q)**2), x).all_coeffs()
    sols = solve(eq + [f.subs(x, 1) - 9], [a, b, c, p, q], dict=True)
    res = set()
    for s in sols:
        if s[p]**2 - 4*s[q] <= 0:
            continue
        g = f.subs(s)
        if diff(g, x).subs(x, 2) < 0:
            res.add(g.subs(x, 4))
    assert len(res) == 1
    return res.pop()

def unique():
    return [standard()]
